/* OverBoard's words in every language: the toolbar, its menus, Settings, the status line and the PDF app's screens.
   Used two ways, like ink-core.js: imported by the PDF app, and inlined into the overlay by tools/build_overlay.py.
   So: plain ES5 function declarations only, no imports, no top-level state. The export line is stripped when inlined.

   Each entry is [English, Español, 中文, Tagalog, Tiếng Việt, Français, Português (Brasil), العربية], in the order of
   obLangs(). {name} marks a value filled in at run time. A missing translation falls back to English.
   To add a language: add it to obLangs() and add one more item to every entry.
   In the HTML, data-t="key" sets an element's text, data-th its HTML, data-tt its tooltip (title),
   data-ta its aria-label and data-tp its placeholder (obTranslate). */

function obLangs(){
  return [["en", "English"], ["es", "Español"], ["zh", "中文"], ["tl", "Tagalog"], ["vi", "Tiếng Việt"], ["fr", "Français"], ["pt", "Português (Brasil)"], ["ar", "العربية"]];
}

/* the language picked in Settings, else the browser's own language if we have it, else English */
function obLang(){
  var codes = obLangs().map(function(l){ return l[0]; }), saved = null;
  try { saved = localStorage.getItem('ob-lang'); } catch(e){}
  if (saved && codes.indexOf(saved) >= 0) return saved;
  var want = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en'];
  for (var i = 0; i < want.length; i++) {
    var base = String(want[i]).toLowerCase().split('-')[0];
    if (base === 'fil') base = 'tl';
    if (codes.indexOf(base) >= 0) return base;
  }
  return 'en';
}

/* t('key', { p: 'P1' }) in the given language */
function obT(lang){
  var all = obStrings(), ix = Math.max(0, obLangs().map(function(l){ return l[0]; }).indexOf(lang));
  function t(key, vars){
    var row = all[key], s = row ? (row[ix] || row[0]) : key;
    return vars ? s.replace(/\{(\w+)\}/g, function(m, k){ return vars[k] === undefined ? m : vars[k]; }) : s;
  }
  t.lang = lang;
  return t;
}

/* put t's words into everything under root marked with data-t / data-th / data-tt / data-ta / data-tp,
   and set lang (and right-to-left for Arabic) on OverBoard's own boxes */
function obTranslate(root, t){
  var marks = [['t', 'textContent'], ['th', 'innerHTML'], ['tt', 'title'], ['ta', 'aria-label'], ['tp', 'placeholder']];
  for (var i = 0; i < marks.length; i++) {
    var els = [].slice.call(root.querySelectorAll('[data-' + marks[i][0] + ']'));
    if (root.hasAttribute && root.hasAttribute('data-' + marks[i][0])) els.unshift(root);
    for (var j = 0; j < els.length; j++) {
      var v = t(els[j].getAttribute('data-' + marks[i][0]));
      if (marks[i][1] === 'aria-label') els[j].setAttribute('aria-label', v);
      else els[j][marks[i][1]] = v;
    }
  }
  var tag = { zh: 'zh-CN', pt: 'pt-BR', tl: 'fil' }[t.lang] || t.lang;
  var boxes = ['ink-bar', 'ink-show', 'ob-filemenu', 'ob-clearmenu', 'ob-hlmenu', 'ob-permenu', 'ob-settings', 'ob-start', 'ob-find', 'ob-toc', 'ob-embed', 'ob-coverwarn'];
  for (i = 0; i < boxes.length; i++) {
    var b = document.getElementById(boxes[i]); if (!b) continue;
    b.setAttribute('lang', tag);
    // text reads right to left in Arabic; the toolbar's own layout stays put so buttons don't jump around
    if (boxes[i] !== 'ink-bar' && boxes[i] !== 'ink-show') { if (t.lang === 'ar') b.setAttribute('dir', 'rtl'); else b.removeAttribute('dir'); }
  }
  var st = document.getElementById('ink-status');
  if (st) { if (t.lang === 'ar') st.setAttribute('dir', 'rtl'); else st.removeAttribute('dir'); }
}

